<?php $badge = function ($s) { include APP_ROOT . '/views/partials/status.php'; }; ?>
<div class="topbar"><div><a class="small" href="/admin/projects">← Projects</a><h1><?= e($p['title']) ?></h1><span class="small muted"><?= e($p['number']) ?> · <?= e($p['name'] ?: $p['email']) ?> · <?= e($p['service_slug']) ?></span></div><div class="row"><?php $badge($p['status']); ?><b><?= (int)$p['progress'] ?>%</b></div></div>
<div class="grid g2" style="align-items:start"><div>
