    <?php if ($m['status'] !== 'done'): ?><form method="post" action="/admin/projects/<?= e($p['number']) ?>" style="margin-left:auto"><?= App\Csrf::field() ?><input type="hidden" name="action" value="milestone"><input type="hidden" name="milestone_id" value="<?= (int)$m['id'] ?>"><button class="btn btn-ghost btn-sm">Mark done</button></form><?php endif; ?></div><?php endforeach; ?></div>
  <form class="panel" method="post" action="/admin/projects/<?= e($p['number']) ?>"><?= App\Csrf::field() ?><input type="hidden" name="action" value="status"><h2>Status</h2><div class="row"><select name="status" style="width:auto"><?php foreach (App\Projects::STATUSES as $s): ?><option<?= $p['status'] === $s ? ' selected' : '' ?>><?= $s ?></option><?php endforeach; ?></select><input name="note" type="text" placeholder="Customer-visible note (optional)" style="flex:1"><button class="btn btn-ghost btn-sm">Update</button></div></form>
  <div class="panel"><h2>Actions</h2><div class="row">
    <form method="post" action="/admin/projects/<?= e($p['number']) ?>"><?= App\Csrf::field() ?><input type="hidden" name="action" value="plan"><button class="btn btn-ghost btn-sm">Ask PM agent to (re)plan</button></form></div>
    <form method="post" action="/admin/projects/<?= e($p['number']) ?>" style="margin-top:12px"><?= App\Csrf::field() ?><input type="hidden" name="action" value="note"><div class="row"><input name="note" type="text" placeholder="Add an update" style="flex:1" required><label class="check small"><input type="checkbox" name="visible" value="1" checked> visible to customer</label><button class="btn btn-ghost btn-sm">Post</button></div></form>
    <form method="post" enctype="multipart/form-data" action="/admin/projects/<?= e($p['number']) ?>" class="row" style="margin-top:12px"><?= App\Csrf::field() ?><input type="hidden" name="action" value="upload"><input type="file" name="file" required><button class="btn btn-ghost btn-sm">Upload deliverable file</button></form></div>
  <div class="panel"><h2>Requirements</h2><?php $req = jdec($p['requirements']); if (!$req): ?><p class="small muted">Not submitted yet.</p><?php endif; ?><?php foreach ($req as $k => $v): ?><p class="small"><b><?= e(label($k)) ?>:</b> <?= nl2br(e($v)) ?></p><?php endforeach; ?>
    <?php foreach ($docs as $d): ?><div class="small"><a href="/documents/<?= (int)$d['id'] ?>"><?= e($d['filename']) ?></a> · <?= e($d['uploaded_by']) ?></div><?php endforeach; ?></div>
</div><div>
  <div class="panel"><h2>Deliverables</h2><?php if (!$deliverables): ?><p class="small muted">Agents' drafts appear here after QA is scheduled.</p><?php endif; ?>
    <?php foreach ($deliverables as $d): ?><details class="card flat" style="margin-bottom:10px"><summary><b><?= e($d['title']) ?></b> <?php $badge($d['status']); ?> QA <?php $badge($d['qa_status']); ?> <span class="small muted">by <?= e($d['produced_by']) ?></span></summary>
      <?php if ($d['qa_notes']): ?><div class="alert alert-info small" style="margin-top:8px"><b>QA:</b> <?= e($d['qa_notes']) ?></div><?php endif; ?>
      <form method="post" action="/admin/deliverables/<?= (int)$d['id'] ?>"><?= App\Csrf::field() ?><textarea name="body" style="min-height:200px;font-family:var(--mono);font-size:.8rem"><?= e($d['body']) ?></textarea><button class="btn btn-ghost btn-sm" style="margin-top:6px">Save edits</button></form>
      <?php if ($d['status'] === 'ready'): ?><form method="post" action="/admin/projects/<?= e($p['number']) ?>" style="margin-top:6px"><?= App\Csrf::field() ?><input type="hidden" name="action" value="deliver"><input type="hidden" name="deliverable_id" value="<?= (int)$d['id'] ?>"><button class="btn btn-primary btn-sm">Send to customer for review</button></form><?php endif; ?></details><?php endforeach; ?></div>
  <div class="panel"><h2>Agent tasks</h2><?php foreach ($tasks as $t): ?><div class="row spread small" style="padding:4px 0"><a href="/admin/tasks/<?= (int)$t['id'] ?>"><?= e($t['title']) ?></a><span><?= e($t['agent_slug']) ?> <?php $badge($t['status']); ?></span></div><?php endforeach; ?><?php if (!$tasks): ?><p class="small muted">None yet.</p><?php endif; ?></div>
  <div class="panel"><h2>Activity</h2><ul class="timeline"><?php foreach ($activity as $a): ?><li><time><?= e(substr($a['created_at'], 0, 16)) ?> · <?= e($a['actor']) ?><?= $a['visible_to_customer'] ? '' : ' · internal' ?></time><?= e($a['summary']) ?></li><?php endforeach; ?></ul></div>
